const SECTIONS=[{"id":1,"name":"C++ 핵심 문법·메모리·STL","count":40},{"id":2,"name":"CUDA 프로그래밍·최적화","count":40},{"id":3,"name":"컴퓨터비전·영상처리","count":35},{"id":4,"name":"딥러닝·ML 기초","count":30},{"id":5,"name":"TensorRT·GPU 추론 최적화","count":25},{"id":6,"name":"병렬 프로그래밍·시스템 설계","count":25},{"id":7,"name":"Python·OpenCV·데이터 처리","count":15},{"id":8,"name":"로봇·센서 융합·통신","count":15},{"id":9,"name":"Linux·빌드·디버깅","count":10},{"id":10,"name":"이력서·프로젝트 검증","count":15},{"id":11,"name":"자동차 머신비전·딥러닝 모델","count":12},{"id":12,"name":"로봇 머신비전·딥러닝 모델","count":12},{"id":13,"name":"공장·제조 머신비전·딥러닝 모델","count":12},{"id":14,"name":"Python · FastAPI · Backend","count":7},{"id":15,"name":"Database · Supabase · Redis","count":7},{"id":16,"name":"LLM · Prompt · RAG","count":7},{"id":17,"name":"AI Agents · LangGraph · MCP","count":7},{"id":18,"name":"AI Workflow · Orchestration","count":7},{"id":19,"name":"Evaluation · Observability · Cost","count":7},{"id":20,"name":"Common · Software Engineering","count":12}];
const QUESTIONS=[{"id":"Q001","title":"포인터와 참조의 차이는?","section":1,"answer":"포인터는 재지정·null이 가능하고 참조는 초기화 시 대상을 정하며 통상 재바인딩하지 않는다. 참조도 댕글링할 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q002","title":"*p와 p의 차이는?","section":1,"answer":"p는 주소를 담는 포인터이고 *p는 그 주소의 객체에 접근하는 역참조 연산이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q003","title":"&a는 무엇인가?","section":1,"answer":"a의 주소를 구하는 주소 연산이다. 오버로드된 operator&나 타입 특성에 따라 예외가 있을 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q004","title":"Stack과 Heap 차이는?","section":1,"answer":"자동 저장 기간 객체와 동적 할당 객체를 구분해야 한다. 스택은 보통 빠른 수명 관리, 힙은 동적 크기·수명 관리에 유리하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q005","title":"new/delete와 malloc/free 차이는?","section":1,"answer":"new는 객체 생성·생성자 호출, delete는 소멸자 호출을 수행한다. malloc/free는 원시 저장 공간 관리다. 서로 섞지 않는다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q006","title":"RAII란?","section":1,"answer":"자원의 획득과 해제를 객체 생명주기에 묶는 패턴이다. 예외 발생에도 소멸자로 자원을 해제한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q007","title":"unique_ptr과 shared_ptr 차이는?","section":1,"answer":"unique_ptr은 단독 소유, shared_ptr은 참조 카운트 기반 공유 소유다. 순환 참조는 weak_ptr로 끊을 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q008","title":"weak_ptr이 필요한 이유는?","section":1,"answer":"shared_ptr 소유권 순환을 막고 공유 대상의 생존 여부를 확인하기 위해서다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q009","title":"얕은 복사와 깊은 복사 차이는?","section":1,"answer":"얕은 복사는 포인터 값 등 내부 참조를 공유할 수 있고, 깊은 복사는 가리키는 자원까지 별도로 복제한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q010","title":"복사 생성자와 복사 대입 연산자 차이는?","section":1,"answer":"생성자는 새 객체를 만들 때, 대입은 이미 존재하는 객체의 상태를 바꿀 때 호출된다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q011","title":"Move Semantics란?","section":1,"answer":"복사 대신 자원의 소유권을 이동해 불필요한 할당·복사를 줄인다. 실제 이동 비용은 타입에 따라 다르다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q012","title":"std::move는 실제로 이동하는가?","section":1,"answer":"아니다. 주로 rvalue 참조로 캐스팅한다. 실제 이동은 이동 생성자·대입 연산자가 수행한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q013","title":"Lvalue와 Rvalue 차이는?","section":1,"answer":"lvalue는 식별 가능한 객체의 위치/정체성과 관련되고, rvalue는 임시값이나 이동 가능한 값을 표현한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q014","title":"Rule of 0/3/5란?","section":1,"answer":"자원 관리를 표준 타입에 위임하면 특수 멤버를 직접 작성하지 않는 Rule of 0가 이상적이다. 직접 관리한다면 복사·이동·소멸 관련 함수를 함께 검토한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q015","title":"const int*와 int* const 차이는?","section":1,"answer":"전자는 가리키는 정수를 수정하지 못하고, 후자는 포인터 자체를 다른 주소로 바꾸지 못한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q016","title":"const 참조를 매개변수로 쓰는 이유는?","section":1,"answer":"큰 객체의 복사를 피하면서 호출 대상의 수정을 제한할 수 있다. 작은 값 타입은 값 전달이 더 나을 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q017","title":"vector::reserve와 resize 차이는?","section":1,"answer":"reserve는 capacity만 확보하고 size를 바꾸지 않는다. resize는 실제 원소 수를 변경한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q018","title":"vector에서 capacity와 size 차이는?","section":1,"answer":"size는 생성된 원소 수, capacity는 재할당 없이 수용 가능한 원소 수다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q019","title":"vector 재할당 시 무엇이 무효화되는가?","section":1,"answer":"재할당되면 기존 원소를 가리키는 반복자·포인터·참조가 무효화된다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q020","title":"vector와 list 선택 기준은?","section":1,"answer":"순회·캐시 친화성이 중요한 경우 vector가 대개 유리하다. list는 특정 위치 삽입·삭제 시 반복자가 유지되는 장점이 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q021","title":"map과 unordered_map 차이는?","section":1,"answer":"map은 보통 균형 트리로 정렬·O(log n), unordered_map은 해시 테이블로 평균 O(1) 탐색이 가능하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q022","title":"std::string_view의 위험은?","section":1,"answer":"문자열 데이터를 소유하지 않으므로 원본 수명 종료 후 댕글링할 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q023","title":"함수 오버로딩과 오버라이딩 차이는?","section":1,"answer":"오버로딩은 같은 이름에 다른 매개변수 목록, 오버라이딩은 파생 클래스가 virtual 함수를 재정의하는 것이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q024","title":"virtual destructor가 필요한 경우는?","section":1,"answer":"기반 클래스 포인터로 파생 객체를 삭제할 수 있는 다형적 기반 타입에 필요하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q025","title":"가상 함수 호출 비용은?","section":1,"answer":"대개 간접 호출과 최적화 제약이 있지만 실제 비용은 코드·분기 예측·인라이닝 가능성에 따라 다르다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q026","title":"템플릿과 런타임 다형성 차이는?","section":1,"answer":"템플릿은 컴파일 시 타입별 코드 생성, virtual 기반 다형성은 런타임 동적 디스패치를 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q027","title":"예외 안전성의 기본 보장은?","section":1,"answer":"실패해도 불변식을 유지하고 자원 누수가 없어야 한다. 강한 보장은 실패 전 상태가 유지된다는 뜻이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q028","title":"noexcept가 이동 성능에 영향을 주는 이유는?","section":1,"answer":"표준 컨테이너가 예외 안전성을 위해 복사 대신 noexcept 이동을 선호할 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q029","title":"Undefined Behavior란?","section":1,"answer":"표준이 동작을 보장하지 않는 상황이다. 결과가 일정하다고 가정하면 안 된다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q030","title":"Dangling pointer란?","section":1,"answer":"객체 수명이 끝난 저장 공간을 계속 가리키는 포인터다. 역참조하면 UB가 발생할 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q031","title":"메모리 누수를 어떻게 찾는가?","section":1,"answer":"RAII 적용, ASan/LSan, Valgrind, 할당 추적, 수명 분석으로 원인을 확인한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q032","title":"ASan과 TSan은 무엇이 다른가?","section":1,"answer":"ASan은 메모리 오염·use-after-free 등에, TSan은 데이터 경합 검출에 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q033","title":"Alignment가 성능에 미치는 영향은?","section":1,"answer":"정렬은 메모리 접근 효율과 SIMD 명령 요구사항에 영향을 주며 과도한 패딩은 메모리 사용량을 늘린다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q034","title":"AoS와 SoA 차이는?","section":1,"answer":"AoS는 객체별 필드를 묶고 SoA는 필드별 배열을 둔다. 연속 필드 접근·SIMD/GPU에 SoA가 유리한 경우가 많다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q035","title":"Cache locality란?","section":1,"answer":"시간적·공간적으로 가까운 데이터의 재사용을 활용해 캐시 미스를 줄이는 특성이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q036","title":"False sharing이란?","section":1,"answer":"서로 다른 스레드가 같은 캐시 라인의 서로 다른 데이터를 수정해 캐시 일관성 비용이 커지는 현상이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q037","title":"컴파일러 최적화 -O2와 -O3 차이는?","section":1,"answer":"일반적으로 -O3가 더 공격적인 최적화를 시도하지만 코드 크기·성능이 항상 좋아지는 것은 아니다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q038","title":"inline 키워드를 쓰면 반드시 인라인되는가?","section":1,"answer":"아니다. 인라인 여부는 컴파일러가 결정한다. inline 키워드는 ODR/다중 정의 규칙과도 관련 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q039","title":"C++ 객체의 lifetime과 scope는 같은가?","section":1,"answer":"아니다. scope는 이름의 가시 범위, lifetime은 객체가 존재하는 기간이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q040","title":"성능 최적화 시 먼저 무엇을 측정하는가?","section":1,"answer":"대표 입력·기준 구현·정확도·시간 측정 구간을 고정하고 프로파일러로 실제 병목부터 확인한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q041","title":"Grid·Block·Thread란?","section":2,"answer":"Grid는 블록의 집합이고 블록은 여러 스레드로 이루어진다. 스레드는 blockIdx/threadIdx로 데이터를 분담한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q042","title":"Warp란?","section":2,"answer":"NVIDIA CUDA에서 보통 32개 스레드로 구성되는 스케줄링 단위다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q043","title":"SIMT는 SIMD와 어떻게 다른가?","section":2,"answer":"SIMT는 각 스레드가 자기 명령 흐름·상태를 갖지만 워프 단위로 함께 실행되는 모델이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q044","title":"Warp divergence란?","section":2,"answer":"워프 내 분기 경로가 달라져 경로별 실행이 직렬화되며 효율이 감소할 수 있는 현상이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q045","title":"Global Memory란?","section":2,"answer":"GPU의 큰 디바이스 메모리 공간으로, 지연이 상대적으로 높아 접근 패턴과 캐시 활용이 중요하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q046","title":"Shared Memory란?","section":2,"answer":"블록 스레드들이 공유하는 온칩 메모리다. 타일링·데이터 재사용 등에 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q047","title":"Constant Memory는 언제 쓰는가?","section":2,"answer":"작고 읽기 전용이며 워프 스레드가 같은 주소를 읽는 경우 브로드캐스트에 유리하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q048","title":"Register pressure란?","section":2,"answer":"스레드당 레지스터 사용량이 많아 동시 상주 워프가 줄거나 spill이 발생하는 문제다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q049","title":"Occupancy란?","section":2,"answer":"SM에 상주하는 활성 워프 수가 하드웨어 최대치에서 차지하는 비율이다. 높은 값이 언제나 빠르진 않다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q050","title":"Memory coalescing이란?","section":2,"answer":"인접 스레드의 메모리 접근이 적은 수의 효율적인 메모리 트랜잭션으로 처리되도록 하는 접근 패턴이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q051","title":"Shared Memory bank conflict란?","section":2,"answer":"서로 다른 주소가 같은 bank에 몰려 접근이 분할되는 현상이다. 예외적으로 동일 주소 브로드캐스트는 유리하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q052","title":"__syncthreads()는 무엇인가?","section":2,"answer":"같은 블록 내 스레드들의 동기화와 공유 메모리 가시성을 보장한다. 조건부 사용 시 참여 조건에 주의한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q053","title":"__syncwarp()는 언제 쓰는가?","section":2,"answer":"필요한 워프 내 스레드들의 동기화에 사용한다. 지정 마스크의 참여 스레드를 일관되게 관리해야 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q054","title":"Atomic 연산은 언제 필요한가?","section":2,"answer":"여러 스레드가 공유 위치를 동시에 수정할 때 원자성을 보장하기 위해 사용한다. 경합 비용을 고려한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q055","title":"Atomic과 reduction의 차이는?","section":2,"answer":"atomic은 공용 주소를 원자적으로 갱신하고 reduction은 계층적으로 부분 결과를 합쳐 경합을 줄일 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q056","title":"Kernel launch overhead란?","section":2,"answer":"커널 실행 요청 자체의 고정 비용이다. 짧은 커널 다수 실행 시 지배적일 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q057","title":"Kernel fusion의 장단점은?","section":2,"answer":"메모리 왕복과 런치 횟수를 줄이지만 레지스터 압박과 코드 복잡도를 늘릴 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q058","title":"Block size는 어떻게 정하는가?","section":2,"answer":"워프 배수의 후보를 두고 레지스터·shared memory·occupancy·실측 처리 시간을 비교한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q059","title":"Grid-stride loop란?","section":2,"answer":"스레드가 자신의 시작 인덱스에서 전체 그리드 간격만큼 증가하며 여러 원소를 처리하는 패턴이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q060","title":"Pinned memory란?","section":2,"answer":"페이지 고정 호스트 메모리다. 비동기 H2D/D2H 전송에 유용하지만 과도한 할당은 시스템에 부담이 된다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q061","title":"Pageable과 pinned memory 비교는?","section":2,"answer":"pinned는 전송 및 비동기 동작에 유리한 경우가 많고 pageable은 관리 부담이 작다. 실제 성능을 측정한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q062","title":"CUDA Stream이란?","section":2,"answer":"명령의 순서와 비동기 실행을 관리하는 큐다. 같은 스트림 내부는 순서를 보장한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q063","title":"Stream으로 연산·복사를 겹치려면?","section":2,"answer":"디바이스의 동시 실행 지원, 별도 스트림, 적절한 pinned memory, 데이터 의존성 관리가 필요하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q064","title":"CUDA Event 측정 시 주의할 점은?","section":2,"answer":"측정 스트림과 동기화 범위를 정확히 설정하고 warm-up·반복·GPU 클록 변동을 고려한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q065","title":"cudaDeviceSynchronize()의 비용은?","section":2,"answer":"호스트를 대기시키고 디바이스 작업 완료를 기다려 파이프라인 병렬성을 줄일 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q066","title":"비동기 커널 오류는 어떻게 확인하는가?","section":2,"answer":"런치 직후 cudaGetLastError와 적절한 동기화 지점의 반환값을 확인한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q067","title":"Nsight Systems와 Compute 차이는?","section":2,"answer":"Systems는 CPU-GPU 타임라인·동시성·병목 흐름, Compute는 개별 커널의 상세 하드웨어 지표를 본다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q068","title":"Compute에서 memory bound를 어떻게 판단하는가?","section":2,"answer":"메모리 대역폭 활용률·요청 패턴·stall 원인·연산 비율을 함께 확인한다. 단일 지표만으로 단정하지 않는다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q069","title":"Roofline model이란?","section":2,"answer":"연산 집약도에 따른 이론적 연산/메모리 성능 상한을 비교해 병목 방향을 파악하는 모델이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q070","title":"Arithmetic intensity란?","section":2,"answer":"전송 바이트당 수행 연산량으로, 주로 FLOPs/byte로 표현한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q071","title":"PCIe 병목을 줄이는 방법은?","section":2,"answer":"전송량 감축, pinned memory, 비동기·배치 전송, GPU 상의 연속 처리, 중복 전송 제거를 고려한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q072","title":"Unified Memory의 장단점은?","section":2,"answer":"프로그래밍은 간편하지만 페이지 이동과 접근 패턴에 따라 지연·오버헤드가 생길 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q073","title":"GPU에 모든 연산을 옮기는 것이 항상 유리한가?","section":2,"answer":"아니다. 데이터 크기·전송·런치 비용이 작은 연산의 이점을 상쇄할 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q074","title":"CPU+GPU 하이브리드 파이프라인을 설계하려면?","section":2,"answer":"연산별 처리량과 전송·의존성을 측정하고 스테이지 병렬성을 고려해 배치·스케줄링한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q075","title":"서로 다른 CUDA 커널을 동시에 돌릴 수 있나?","section":2,"answer":"자원 여유와 하드웨어 지원 조건에서 다른 스트림의 커널이 동시 실행될 수 있지만 보장되지는 않는다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q076","title":"레이스 컨디션을 GPU에서 확인하는 방법은?","section":2,"answer":"compute-sanitizer racecheck 등과 반복 검증으로 위험을 찾고 동기화·소유권을 재설계한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q077","title":"Thrust와 직접 CUDA 커널 선택 기준은?","section":2,"answer":"표준 병렬 알고리즘으로 충분하면 Thrust가 생산성이 높고 특수 패턴·융합이 중요하면 커스텀 커널을 고려한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q078","title":"CUDA Graph는 언제 유리한가?","section":2,"answer":"반복되는 고정/유사 작업 그래프에서 CPU 런치 오버헤드를 줄이는 데 유용하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q079","title":"처리량과 지연시간 중 무엇을 최적화하는가?","section":2,"answer":"서비스 SLA/라인 takt time을 먼저 정한다. 배치와 동시성은 처리량을 높이지만 지연시간을 악화시킬 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q080","title":"커널 10배 가속인데 시스템이 1.2배만 빨라진 이유는?","section":2,"answer":"전체 시간에서 그 커널이 차지한 비율·전송·CPU 전처리·동기화 등 Amdahl의 법칙을 확인한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q081","title":"Convolution과 correlation 차이는?","section":3,"answer":"수학적 convolution은 커널을 뒤집고 correlation은 뒤집지 않는다. 많은 라이브러리의 필터 연산은 correlation 형태다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q082","title":"Gaussian blur의 목적은?","section":3,"answer":"고주파 잡음을 줄이고 특징 검출 전 안정화하지만 세부 경계도 흐릴 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q083","title":"Sobel 연산자는 무엇을 계산하나?","section":3,"answer":"x/y 방향 영상 기울기를 근사해 에지의 방향과 크기를 구한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q084","title":"Canny edge의 단계는?","section":3,"answer":"평활화, 기울기 계산, 비최대 억제, 이중 임계값과 hysteresis로 에지를 연결한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q085","title":"Thresholding과 adaptive threshold 차이는?","section":3,"answer":"전자는 전역 임계값, 후자는 지역 밝기 통계에 따라 임계값을 다르게 적용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q086","title":"Morphology erosion과 dilation 차이는?","section":3,"answer":"침식은 전경을 축소하고 팽창은 전경을 확장한다. 조합으로 opening/closing을 만든다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q087","title":"Connected Components란?","section":3,"answer":"이진 영상에서 인접한 전경 픽셀을 연결 성분별로 레이블링하는 기법이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q088","title":"Contour와 bounding box 차이는?","section":3,"answer":"Contour는 경계 형태, bounding box는 이를 감싸는 단순 사각형이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q089","title":"Template matching의 전제는?","section":3,"answer":"비교할 패턴의 기하·조명 변화가 충분히 제한되어 있거나 정규화/변형 모델로 보정 가능해야 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q090","title":"NCC와 SSD 차이는?","section":3,"answer":"NCC는 정규화 상관도로 밝기·대비 차이에 상대적으로 강하고 SSD는 픽셀 차의 제곱합을 최소화한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q091","title":"회전 불변 template matching은 어떻게 구현하나?","section":3,"answer":"회전 후보 검색, 방향 정렬, 특징 기반 매칭 등을 고려하고 후보 수에 따른 비용을 줄인다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q092","title":"멀티스케일 영상처리의 장점은?","section":3,"answer":"피라미드로 크기 변화를 탐색하거나 큰 구조를 먼저 찾아 검색 범위를 줄일 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q093","title":"Histogram equalization과 CLAHE 차이는?","section":3,"answer":"전역 대비 보정과 지역 타일 기반 제한 대비 보정이다. CLAHE는 노이즈 증폭도 제한한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q094","title":"카메라 내부·외부 파라미터란?","section":3,"answer":"내부는 초점거리·주점 등 투영 특성, 외부는 월드/카메라 사이 회전·병진이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q095","title":"카메라 왜곡 보정은 왜 필요한가?","section":3,"answer":"렌즈의 radial/tangential distortion을 보정해 기하 관계와 측정 정확도를 높인다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q096","title":"Homography가 가능한 조건은?","section":3,"answer":"평면 장면 또는 순수 회전 등 조건에서 두 영상 사이의 사영 변환을 표현한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q097","title":"Stereo depth 원리는?","section":3,"answer":"대응점 disparity와 카메라 baseline·초점거리로 깊이를 삼각측량한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q098","title":"RGB-D와 LiDAR의 차이는?","section":3,"answer":"RGB-D는 영상과 정렬된 깊이를 제공하고 LiDAR는 거리 샘플을 직접 측정한다. 범위·해상도·환경 강인성이 다르다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q099","title":"Object Detection과 Classification 차이는?","section":3,"answer":"분류는 이미지/영역의 클래스를 예측하고 검출은 객체 위치와 클래스를 예측한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q100","title":"Semantic·Instance segmentation 차이는?","section":3,"answer":"Semantic은 픽셀 클래스, Instance는 같은 클래스 내 객체 인스턴스까지 구분한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q101","title":"YOLO 계열 탐지기의 특징은?","section":3,"answer":"하나의 네트워크 추론으로 위치·클래스를 예측하는 단일 단계 검출 계열이다. 버전에 따라 내부 구조가 다르다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q102","title":"Anchor-based와 anchor-free 차이는?","section":3,"answer":"기준 박스(anchor)에 상대 예측하는 방식과 명시적 anchor 없이 위치를 예측하는 접근의 차이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q103","title":"IoU란?","section":3,"answer":"두 영역의 교집합 면적을 합집합 면적으로 나눈 비율이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q104","title":"NMS란?","section":3,"answer":"중복된 박스 중 점수 높은 결과를 우선 남기고 일정 겹침 이상의 후보를 억제하는 후처리다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q105","title":"Precision과 Recall의 트레이드오프는?","section":3,"answer":"임계값 조정에 따라 오탐과 미탐이 달라진다. 검사 공정은 미탐 비용을 특히 따져야 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q106","title":"mAP는 무엇인가?","section":3,"answer":"클래스별 precision-recall 곡선의 평균 정밀도(AP)를 계산하고 이를 클래스/IoU 기준으로 평균한 지표다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q107","title":"Tracking과 Detection의 차이는?","section":3,"answer":"Detection은 프레임별 객체 위치, Tracking은 프레임 간 동일 객체 ID를 연계한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q108","title":"Kalman filter는 Tracking에서 왜 쓰나?","section":3,"answer":"상태와 불확실성을 모델링해 관측 사이 움직임을 예측하고 관측으로 보정한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q109","title":"Hungarian matching은 언제 쓰나?","section":3,"answer":"트랙과 검출 결과의 비용 행렬을 바탕으로 일대일 할당을 구할 때 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q110","title":"Optical flow란?","section":3,"answer":"연속 프레임의 픽셀/특징 이동 벡터를 추정하는 방법이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q111","title":"검사 영상에서 조명 편차를 줄이는 법은?","section":3,"answer":"조명 하드웨어 통제, 정규화, 평탄화, 기준 이미지 보정, 견고한 특징을 고려한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q112","title":"이미지 전처리를 GPU로 옮길 기준은?","section":3,"answer":"픽셀 수·배치 크기·메모리 이동·연산 복잡도·전체 지연 예산을 실측해 결정한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q113","title":"결함 탐지에서 픽셀 정확도 외에 볼 지표는?","section":3,"answer":"객체/제품 단위 Recall, false reject rate, 결함 크기별 성능, 처리량, 검사 시간이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q114","title":"데이터 누수는 영상 데이터에서 어떻게 발생하나?","section":3,"answer":"동일 제품·같은 촬영 시퀀스·유사 이미지가 train/test에 동시에 들어가면 일반화 성능이 과대평가된다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q115","title":"산업 검사에서 실시간성을 어떻게 정의하나?","section":3,"answer":"라인 속도·제품별 이미지 수·최악 지연시간·버퍼 누적·미탐 허용 수준으로 정의한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q116","title":"Supervised와 unsupervised learning 차이는?","section":4,"answer":"지도학습은 정답 레이블로 목표를 학습하고 비지도학습은 레이블 없이 구조·표현을 학습한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q117","title":"Train/validation/test 역할은?","section":4,"answer":"학습은 파라미터 갱신, 검증은 모델 선택·튜닝, 테스트는 최종 일반화 성능 추정에 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q118","title":"Overfitting이란?","section":4,"answer":"학습 데이터에 과하게 맞아 새로운 데이터 성능이 떨어지는 현상이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q119","title":"Bias-variance tradeoff란?","section":4,"answer":"모델의 과도한 단순화에 따른 편향과 데이터 변화에 대한 민감도 사이 균형이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q120","title":"CNN이 영상에 유리한 이유는?","section":4,"answer":"지역 연결과 가중치 공유로 공간 패턴을 효율적으로 학습한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q121","title":"Convolution layer의 stride와 padding은?","section":4,"answer":"stride는 필터 이동 간격, padding은 경계 확장 방식으로 출력 해상도에 영향을 준다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q122","title":"Pooling의 역할은?","section":4,"answer":"공간 크기를 줄이고 지역 특징을 집계한다. 정보 손실 가능성이 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q123","title":"ReLU의 장단점은?","section":4,"answer":"계산이 단순하고 기울기 소실을 완화하지만 음수 영역에서 죽은 뉴런이 생길 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q124","title":"Sigmoid와 Softmax 차이는?","section":4,"answer":"sigmoid는 각 출력의 독립적 0~1 변환, softmax는 클래스 출력의 합이 1인 분포를 만든다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q125","title":"Cross-entropy loss는?","section":4,"answer":"정답 분포와 예측 분포의 불일치를 벌점화하는 분류 손실이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q126","title":"Focal loss는 왜 쓰나?","section":4,"answer":"쉬운 샘플의 기여를 줄이고 어려운/희소한 샘플에 집중하도록 설계된 손실이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q127","title":"Class imbalance 대응법은?","section":4,"answer":"클래스 가중치·샘플링·증강·focal loss·임계값 조정과 PR 기반 평가를 검토한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q128","title":"Batch normalization의 역할은?","section":4,"answer":"배치 통계와 학습 가능한 변환으로 중간 활성값을 정규화하며 학습 안정성에 도움을 줄 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q129","title":"Batch norm과 Layer norm 차이는?","section":4,"answer":"정규화 축과 학습/추론 통계 사용 방식이 다르다. LayerNorm은 샘플의 특징 축 기준이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q130","title":"Dropout은 왜 사용하나?","section":4,"answer":"학습 중 일부 활성값을 무작위로 제거해 과적합을 완화하는 정규화 기법이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q131","title":"Gradient descent와 Adam 차이는?","section":4,"answer":"SGD는 경사 기반 직접 갱신, Adam은 1·2차 모멘트 추정을 활용한 적응적 갱신을 수행한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q132","title":"Learning rate가 너무 크거나 작으면?","section":4,"answer":"너무 크면 발산/진동, 너무 작으면 학습이 느리거나 부적절한 지점에 오래 머문다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q133","title":"Vanishing gradient란?","section":4,"answer":"역전파 경사가 지나치게 작아져 초기 계층 학습이 어려워지는 현상이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q134","title":"Data augmentation의 목적은?","section":4,"answer":"의미 있는 변형을 추가해 데이터 다양성을 높이고 일반화 성능을 개선한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q135","title":"제조 이미지에서 위험한 augmentation은?","section":4,"answer":"결함의 방향·크기·색·위치가 의미를 갖는데 이를 파괴하는 변형은 잘못된 레이블을 유발한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q136","title":"Transfer learning이란?","section":4,"answer":"사전 학습된 모델의 표현·가중치를 새로운 작업에 재사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q137","title":"Fine tuning과 feature extraction 차이는?","section":4,"answer":"전자는 사전 학습 가중치 일부/전부를 업데이트하고 후자는 특징 추출기를 고정한 채 헤드 등을 학습한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q138","title":"Precision·Recall·F1이란?","section":4,"answer":"정밀도는 예측 양성 중 참양성, 재현율은 실제 양성 중 참양성, F1은 두 값의 조화평균이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q139","title":"ROC-AUC와 PR-AUC 선택 기준은?","section":4,"answer":"양성 희소도가 큰 문제에서는 PR-AUC가 양성 검출 품질에 더 직접적일 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q140","title":"Confusion matrix란?","section":4,"answer":"TP/FP/FN/TN 등 실제 레이블과 예측 결과를 교차 집계하는 표다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q141","title":"Calibration이란?","section":4,"answer":"모델 확률 점수가 실제 발생 빈도와 얼마나 일치하는지 평가·보정하는 것이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q142","title":"Domain shift란?","section":4,"answer":"학습 데이터와 운영 데이터의 분포가 달라지는 현상이다. 조명·카메라·공정 변화가 예다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q143","title":"Active learning은?","section":4,"answer":"모델이 불확실하거나 유익하다고 판단한 샘플을 우선 레이블링해 효율을 높이는 방법이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q144","title":"Anomaly detection과 supervised defect classification 차이는?","section":4,"answer":"이상탐지는 정상 패턴과의 이탈을 이용할 수 있고 지도 결함 분류는 알려진 결함의 레이블을 학습한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q145","title":"모델 성능 저하가 발생하면 어떻게 분석하나?","section":4,"answer":"데이터 품질·입력 분포·전처리·버전·레이블·모델·임계값을 분리해 점검한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q146","title":"PyTorch와 TensorRT 차이는?","section":5,"answer":"PyTorch는 모델 개발·학습에 폭넓고 TensorRT는 NVIDIA GPU 추론 엔진 구축·최적화에 특화돼 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q147","title":"TensorRT 엔진이란?","section":5,"answer":"특정 네트워크·설정·대상 환경에 맞춰 최적화된 추론 실행 표현이다. 호환성 제약을 고려한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q148","title":"ONNX의 역할은?","section":5,"answer":"프레임워크 간 모델 그래프·연산을 교환하는 중간 표현으로 자주 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q149","title":"ONNX 변환 시 실패하는 이유는?","section":5,"answer":"미지원 연산, 동적 shape, 버전 차이, 커스텀 연산, 수치·레이아웃 차이 등이 원인일 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q150","title":"FP32·FP16·INT8 차이는?","section":5,"answer":"정밀도·표현 범위·메모리 사용량·하드웨어 처리량이 다르며 실제 정확도와 속도를 검증해야 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q151","title":"INT8 quantization에서 calibration은?","section":5,"answer":"정수화 스케일을 추정하기 위해 대표 활성값 분포를 수집·분석하는 과정이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q152","title":"QAT와 PTQ 차이는?","section":5,"answer":"QAT는 양자화 영향을 학습 중 반영하고 PTQ는 학습 완료 후 정수화를 적용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q153","title":"Tensor Core를 활용하려면?","section":5,"answer":"지원 GPU·연산 형태·dtype·차원 조건·레이아웃이 적합해야 한다. 실제 활용 여부를 프로파일링한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q154","title":"Batch Size 증가의 효과는?","section":5,"answer":"대개 처리량 개선 여지가 있지만 대기·메모리·지연시간이 늘 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q155","title":"Dynamic shape가 최적화에 미치는 영향은?","section":5,"answer":"범위와 최적 프로파일 설정에 따라 엔진의 tactic 선택·메모리·성능이 달라진다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q156","title":"Preprocess와 postprocess를 포함해 측정해야 하나?","section":5,"answer":"서비스 E2E 지연을 평가할 때는 반드시 포함하고 순수 엔진 성능은 별도 분리해 기록한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q157","title":"GPU inference latency 측정법은?","section":5,"answer":"warm-up 후 동기화와 정확한 측정 경계를 적용하고 p50/p95/p99·처리량을 함께 측정한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q158","title":"Throughput과 latency 차이는?","section":5,"answer":"처리량은 단위 시간당 완료 작업 수, 지연은 개별 요청 완료까지 걸린 시간이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q159","title":"TensorRT tactic 선택이란?","section":5,"answer":"지원 구현 후보들 중 모델·shape·환경에 적합한 커널 알고리즘을 선택하는 과정이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q160","title":"Plugin이 필요한 경우는?","section":5,"answer":"TensorRT가 직접 지원하지 않거나 특수 구현이 필요한 연산을 확장할 때 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q161","title":"Zero-copy는 언제 유용한가?","section":5,"answer":"장치·메모리 구조와 접근 패턴이 적절할 때 복사 비용을 줄이지만 항상 빠른 것은 아니다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q162","title":"NMS를 CPU에서 수행할 때 병목은?","section":5,"answer":"검출 결과의 전송과 CPU 후처리 시간이 전체 지연을 지배할 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q163","title":"GPU에서 여러 모델 동시 실행할 때 이슈는?","section":5,"answer":"VRAM 경쟁, SM/대역폭 경합, 스케줄링 지연, 동기화, 예측 불가능한 tail latency가 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q164","title":"CUDA Stream과 TensorRT 실행 연결은?","section":5,"answer":"실행 컨텍스트와 사용자 스트림을 적절히 관리해 엔진 실행과 전후처리 의존성을 제어한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q165","title":"엔진과 실행 컨텍스트 관계는?","section":5,"answer":"엔진은 최적화된 모델 표현이고 실행 컨텍스트는 해당 엔진의 실제 추론 상태·실행을 관리한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q166","title":"Batching 전략을 어떻게 선택하나?","section":5,"answer":"입력 도착률·SLA·모델 효율·VRAM을 바탕으로 정적/동적 배치 크기와 최대 대기 시간을 정한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q167","title":"모델 전환 없이 성능을 높일 방법은?","section":5,"answer":"전처리/후처리, 배치, 복사, 스케줄링, 연산 정밀도, 병렬성, 커널 병목을 측정해 개선한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q168","title":"정확도 동등성은 어떻게 검증하나?","section":5,"answer":"공통 입력에서 출력 오차·후처리 결과·최종 지표를 비교하고 허용 오차를 명시한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q169","title":"서빙 최적화에서 가장 중요한 운영 지표는?","section":5,"answer":"서비스 목표에 따라 E2E p95/p99 지연, QPS, GPU/메모리 사용량, 오류율, 정확도 변화다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q170","title":"작은 모델인데 느린 원인은?","section":5,"answer":"전처리/후처리, 잦은 런치, H2D/D2H, 동기화, CPU 스케줄링, 낮은 배치 효율을 먼저 본다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q171","title":"Process와 thread 차이는?","section":6,"answer":"프로세스는 독립 주소 공간을, 스레드는 같은 프로세스 메모리를 공유하며 실행 흐름을 분리한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q172","title":"Race condition이란?","section":6,"answer":"실행 순서에 따라 결과가 달라지는 현상이다. 동기화되지 않은 공유 데이터 접근은 데이터 경합이 될 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q173","title":"Mutex의 역할은?","section":6,"answer":"임계구역에서 공유 자원의 동시 접근을 제어한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q174","title":"Deadlock 발생 조건은?","section":6,"answer":"상호 배제·점유 대기·비선점·순환 대기가 동시에 충족되면 발생 가능하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q175","title":"Deadlock을 줄이는 방법은?","section":6,"answer":"락 순서 통일, 짧은 임계구역, try_lock·타임아웃, 소유권 설계를 적용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q176","title":"Lock-free와 wait-free 차이는?","section":6,"answer":"lock-free는 시스템 전체 진행을, wait-free는 각 스레드의 유한 단계 내 완료를 보장하는 진행 조건이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q177","title":"Atomic과 mutex 선택 기준은?","section":6,"answer":"간단한 독립 상태는 atomic이 적합할 수 있고 복합 불변식·다중 필드는 mutex가 이해·검증에 유리하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q178","title":"Condition variable이란?","section":6,"answer":"특정 조건이 충족될 때까지 스레드가 대기하도록 돕는 동기화 수단이다. 조건을 루프로 재확인한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q179","title":"Producer-consumer 패턴이란?","section":6,"answer":"데이터 생산 단계와 소비 단계를 큐로 분리해 처리 속도 차이를 흡수한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q180","title":"Bounded queue가 필요한 이유는?","section":6,"answer":"소비가 느릴 때 무제한 메모리 증가를 막고 역압을 적용하기 위해서다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q181","title":"Backpressure란?","section":6,"answer":"하위 단계가 처리 가능한 양에 맞춰 상위 단계 입력 속도를 제어하는 메커니즘이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q182","title":"Thread pool을 쓰는 이유는?","section":6,"answer":"스레드 생성·소멸 비용을 줄이고 작업 개수와 자원 활용을 관리하기 위해서다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q183","title":"Context switching이 많은 이유는?","section":6,"answer":"과도한 스레드 수, 블로킹·락 경합, 작업 단위 과소화 등으로 증가할 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q184","title":"Amdahl의 법칙이란?","section":6,"answer":"프로그램 중 개선 가능한 부분의 비율이 전체 속도 향상의 상한을 제한한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q185","title":"Pipeline parallelism과 data parallelism 차이는?","section":6,"answer":"전자는 작업의 단계를 겹치고 후자는 같은 연산을 여러 데이터에 나눠 수행한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q186","title":"Latency budget을 어떻게 만든다?","section":6,"answer":"취득·전처리·추론·후처리·전송·UI 등 단계별 허용 시간을 분배하고 최악 지연을 감시한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q187","title":"실시간 시스템에서 평균 시간만 보면 안 되는 이유는?","section":6,"answer":"긴 tail latency가 버퍼 누적·마감시간 위반을 일으킬 수 있기 때문이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q188","title":"Ring buffer의 장점은?","section":6,"answer":"고정 메모리 기반의 순환 저장으로 스트리밍 데이터의 할당 비용을 줄일 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q189","title":"Double buffering이란?","section":6,"answer":"한 버퍼를 처리하는 동안 다른 버퍼를 채워 취득·처리를 겹치는 방식이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q190","title":"Zero-copy 설계 시 주의점은?","section":6,"answer":"수명, 소유권, 메모리 일관성, 접근 위치 및 실제 캐시/전송 비용을 고려한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q191","title":"CPU affinity를 언제 조정하나?","section":6,"answer":"지연 변동이 중요하고 스레드 이동·캐시 영향이 측정될 때 코어 배치를 검토한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q192","title":"NUMA가 성능에 미치는 영향은?","section":6,"answer":"CPU 소켓별 메모리 접근 지연·대역폭이 달라 데이터와 스레드의 위치가 중요하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q193","title":"로그를 어디에 심어야 하나?","section":6,"answer":"스테이지 시작/종료, 큐 깊이, 처리량, p95 지연, 오류와 재시도 경로를 추적 가능하게 기록한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q194","title":"부하 테스트와 스트레스 테스트 차이는?","section":6,"answer":"부하는 목표 조건에서 동작을 검증하고 스트레스는 한계를 넘겨 장애·복구 특성을 살핀다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q195","title":"장비 12개 영상 입력 파이프라인을 설계한다면?","section":6,"answer":"입력 타임스탬프·제품 ID·버퍼·CPU/GPU 역할·드롭 정책·추론/검사 순서·출력 SLA를 명확히 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q196","title":"Python GIL이란?","section":7,"answer":"일반적인 CPython의 GIL은 한 인터프리터 내 Python 바이트코드 실행을 제한하지만 I/O·네이티브 연산은 예외가 있다. 버전/빌드에 따라 달라진다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q197","title":"Threading과 multiprocessing 차이는?","section":7,"answer":"Thread는 메모리를 공유하고 프로세스는 독립 주소 공간을 사용하며 CPU 병렬성과 직렬화 비용이 다르다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q198","title":"Generator가 유리한 상황은?","section":7,"answer":"대량 데이터를 한 번에 메모리에 올리지 않고 지연 평가·스트리밍할 때다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q199","title":"NumPy vectorization이 빠른 이유는?","section":7,"answer":"원소별 Python 루프 대신 최적화된 네이티브 배열 연산을 수행하기 때문이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q200","title":"NumPy view와 copy 차이는?","section":7,"answer":"view는 원본 메모리를 공유하고 copy는 별도 데이터를 보유한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q201","title":"np.ndarray의 stride란?","section":7,"answer":"차원별 인덱스 증가 시 이동하는 바이트 수이며 연속 메모리 여부에 영향을 준다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q202","title":"OpenCV BGR과 RGB 문제는?","section":7,"answer":"OpenCV 기본 읽기 색상 순서는 보통 BGR이라 모델 입력 RGB와 혼동하면 정확도가 떨어질 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q203","title":"cv2.imread와 imdecode 차이는?","section":7,"answer":"imread는 파일 경로에서 디코딩하고 imdecode는 메모리의 인코딩 바이트에서 디코딩한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q204","title":"OpenCV 이미지 깊이 uint8/uint16 차이는?","section":7,"answer":"픽셀 값의 표현 범위와 메모리 사용량이 다르므로 정규화·연산 오버플로를 주의한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q205","title":"데이터셋 split을 어떻게 설계하나?","section":7,"answer":"동일 제품·웨이퍼·촬영 세션·설비 단위 중 누수 위험이 있는 그룹을 분리한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q206","title":"DataLoader 병목을 찾는 방법은?","section":7,"answer":"디스크 I/O, decode, augmentation, batch 조립, CPU→GPU 전송 시간을 단계별 측정한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q207","title":"파일 수가 많을 때 로딩 최적화는?","section":7,"answer":"저장 포맷·읽기 병렬성·압축/디코딩 비용·캐시·배치 접근을 실험한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q208","title":"Pandas pickle을 읽을 때 주의점은?","section":7,"answer":"메모리 사용량과 버전 호환성을 확인하고 신뢰하지 않는 pickle은 코드 실행 위험 때문에 읽지 않는다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q209","title":"학습 재현성을 높이는 방법은?","section":7,"answer":"시드, split, 코드·패키지·데이터·모델 버전, 하드웨어와 비결정성 조건을 기록한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q210","title":"전처리 코드의 정확성을 검증하는 방법은?","section":7,"answer":"대표 이미지와 경계 사례에 대한 단위 테스트·시각적 검사·전후 통계·모델 지표를 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q211","title":"AMR과 AGV 차이는?","section":8,"answer":"AMR은 환경 인지 기반 경로 변경이 가능하고 AGV는 상대적으로 고정 경로 운용을 전제로 하는 경우가 많다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q212","title":"Forward kinematics란?","section":8,"answer":"관절 상태로부터 로봇 말단의 위치와 자세를 계산하는 것이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q213","title":"Inverse kinematics란?","section":8,"answer":"목표 말단 위치·자세를 달성하는 관절 구성을 계산하는 것이다. 해가 여러 개 또는 없을 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q214","title":"좌표계 변환을 왜 관리하나?","section":8,"answer":"카메라·로봇·월드·센서 좌표가 다르기 때문에 측정·제어 일관성을 위해 변환 체인을 유지해야 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q215","title":"Hand-eye calibration이란?","section":8,"answer":"카메라 좌표계와 로봇 말단/베이스 좌표계 간 강체 변환을 추정하는 과정이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q216","title":"3D bin picking 파이프라인은?","section":8,"answer":"깊이 취득→객체/파지 후보 추정→좌표 변환→충돌 검증→로봇 동작→성공 판정이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q217","title":"Radar와 camera의 장단점은?","section":8,"answer":"레이더는 거리·상대속도에 강하고 카메라는 시각적 분류·해상도에 강하다. 환경과 센서 특성이 다르다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q218","title":"센서 fusion의 early/late fusion 차이는?","section":8,"answer":"early는 특징/원시 데이터를 이른 단계에서 결합, late는 각 센서의 추론 결과를 뒤에서 결합한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q219","title":"시간 동기화가 중요한 이유는?","section":8,"answer":"이동 객체의 센서 측정 시점이 다르면 잘못된 연관·거리 추정이 발생한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q220","title":"데이터 association이란?","section":8,"answer":"서로 다른 프레임/센서의 관측이 동일 객체에 속하는지 대응시키는 과정이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q221","title":"REST와 TCP/IP의 관계는?","section":8,"answer":"REST는 애플리케이션 설계 스타일이며 HTTP가 일반적으로 TCP/IP 위에서 동작한다. 계층이 다른 개념이다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q222","title":"Modbus TCP와 Digital I/O 차이는?","section":8,"answer":"전자는 네트워크 프로토콜로 레지스터·코일을 읽고 쓰며 후자는 물리적 이산 신호를 주고받는다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q223","title":"장비 통신이 끊기면?","section":8,"answer":"타임아웃·재시도 정책·안전 상태·중복 명령 방지·상태 복구 절차를 설계한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q224","title":"산업 로봇 통합에서 안전을 어떻게 고려하나?","section":8,"answer":"비상정지·인터록·안전 PLC 등 인증된 안전 체계와 별도로 소프트웨어 상태 관리를 설계한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q225","title":"전시 데모 3배 가속의 타당성을 어떻게 증명하나?","section":8,"answer":"동일 시작·종료 조건에서 사이클 타임 분포·성공률·정지 횟수·재시도 비용을 전후 비교한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q226","title":"CMake는 무엇인가?","section":9,"answer":"다양한 플랫폼·빌드 시스템을 위한 빌드 설정을 생성하고 의존성을 관리하는 도구다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q227","title":"Static과 dynamic linking 차이는?","section":9,"answer":"정적 링크는 라이브러리 코드를 바이너리에 포함하고 동적 링크는 실행/로드 시 공유 라이브러리를 연결한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q228","title":"Debug와 Release 빌드 차이는?","section":9,"answer":"최적화·디버그 심볼·검증 옵션 등이 다르며 결과와 성능도 달라질 수 있다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q229","title":"gdb로 segmentation fault를 찾으려면?","section":9,"answer":"심볼이 있는 빌드와 재현 입력으로 실행하고 backtrace·변수·메모리 접근을 검사한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q230","title":"core dump의 용도는?","section":9,"answer":"프로세스 충돌 시 메모리·스레드 상태를 사후 분석하는 데 사용한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q231","title":"Linux top과 perf의 차이는?","section":9,"answer":"top은 시스템/프로세스 자원 개요, perf는 CPU 이벤트·함수별 성능 프로파일링에 유용하다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q232","title":"Docker가 모델 배포에 주는 이점은?","section":9,"answer":"실행 환경·의존성 재현성을 높이지만 GPU 드라이버·디바이스 호환성을 별도 관리해야 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q233","title":"CI에서 무엇을 검증해야 하나?","section":9,"answer":"빌드, 단위·통합 테스트, 정적 분석, 최소 추론/성능 회귀 테스트 등을 자동화한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q234","title":"CUDA 버전 호환성 점검은?","section":9,"answer":"드라이버, CUDA 런타임/툴킷, PyTorch/TensorRT 바이너리, GPU 아키텍처의 지원 관계를 확인한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q235","title":"성능 회귀를 어떻게 방지하나?","section":9,"answer":"입력·환경이 통제된 벤치마크와 허용 편차, 버전별 결과 기록 및 알림을 운영한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q236","title":"11.2배 속도 향상은 어떤 기준인가?","section":10,"answer":"단일 코어 CPU 대비 수치임을 명확히 하고 동일 입력·측정 범위·반복 횟수·환경을 설명한다. 측정하지 않은 조건은 추측하지 않는다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q237","title":"멀티코어 CPU 대비 약 40% 개선과 11.2배는 모순 아닌가?","section":10,"answer":"서로 다른 기준선이다. 단일 코어 대비 배수와 멀티코어 CPU-only 대비 향상률을 각각 정의한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q238","title":"2.52M images/h는 어떻게 계산했나?","section":10,"answer":"210,000 tablets/h × 12 images/tablet = 2,520,000 images/h이며 취득·처리 처리량의 측정 맥락을 구분한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q239","title":"12개 이미지 중 8개만 GPU로 처리한 이유는?","section":10,"answer":"연산별 CPU/GPU 실행시간·전송·동기화 비용·의존성 측정에 따른 선택적 오프로딩이라고 설명하고 근거를 준비한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q240","title":"10s~100s배 커널 속도 향상을 검증하려면?","section":10,"answer":"커널 단독 기준과 비교 CPU 기준, 입력·정확도·측정 방법을 명시하고 전체 시스템 개선과 분리한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q241","title":"Nsight로 실제 어떤 병목을 찾았나?","section":10,"answer":"기억나는 구체적 타임라인/커널 지표와 변경 전후 실측을 제시한다. 확인하지 못한 지표를 만들어 말하지 않는다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q242","title":"자체 개발 검사 알고리즘을 공개할 수 없는데 설명은?","section":10,"answer":"비밀 알고리즘·코드 대신 입력/출력 계약, 병목 유형, 최적화 방법, 측정 프로토콜과 비밀유지 경계를 설명한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q243","title":"DriveFusion에서 YOLO11n TensorRT DLL 구조는?","section":10,"answer":"CARLA 센서 수집과 C++/TensorRT 추론 모듈·트래킹·융합·Qt UI·평가 흐름을 분리해 설명한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q244","title":"DriveFusion의 MAE -5.41% 의미는?","section":10,"answer":"9개 세션의 공통 16,491개 샘플에서 비교한 전체 MAE 감소율이다. 비교 기준과 데이터 조건을 함께 밝혀야 한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q245","title":"Radar 적용 437개에서 -39.42%의 의미는?","section":10,"answer":"레이더 보정이 적용된 하위집합 결과이며 전체 데이터로 일반화하거나 전체 개선율과 혼동하면 안 된다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q246","title":"센서 fusion이 오히려 나빠지는 사례는?","section":10,"answer":"센서 시간 불일치, 부정확한 association, 잘못된 외부 파라미터, 레이더 오검출 등으로 설명한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q247","title":"로봇 시스템 통합에서 본인 역할은?","section":10,"answer":"기존 로봇 하드웨어 설계가 아니라 장비 간 통신·전장 배선·제어 조정·전시/현장 구동이라는 범위를 정확히 구분한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q248","title":"3배 빠른 전시 시스템을 어떻게 만들었나?","section":10,"answer":"모듈화·동작 순서 재구성·그리퍼/베이스 개선과 안정성 확보를 설명하되 실제 측정 조건을 준비한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q249","title":"개인 프로젝트와 회사 경험의 차이는?","section":10,"answer":"회사에서는 실시간성·안정성·운영 제약이 컸고 개인 프로젝트에서는 설계 자유도·검증 범위를 명확히 말한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q250","title":"왜 CUDA에서 딥러닝 추론 최적화로 확장하려 하나?","section":10,"answer":"기존의 저수준 GPU 최적화 역량을 CV 모델 추론·서빙에 적용해 시스템 전체 성능을 높이려는 방향임을 구체적으로 설명한다.","follow":"이 개념을 실제 코드·프로파일러·프로젝트에서 어떻게 검증하겠는가?"},{"id":"Q251","title":"YOLO 검출기는 자동차 인지 파이프라인에서 무엇을 출력하는가?","section":11,"answer":"YOLO는 이미지에서 차량·보행자·자전거 등의 클래스, bounding box, confidence를 예측한다. 검출 결과만으로 실제 거리·속도·충돌 위험까지 알 수는 없으며 추적과 센서 융합이 필요하다.","follow":"카메라 단독 검출과 레이더 결합 시 평가 지표를 어떻게 분리하겠는가?"},{"id":"Q252","title":"Faster R-CNN과 YOLO는 어떻게 다른가?","section":11,"answer":"Faster R-CNN은 제안 영역 기반 two-stage 검출기이고 YOLO는 dense 예측 기반 one-stage 검출기다. 일반적으로 실시간에는 YOLO 계열이 유리하지만 실제 속도와 정확도는 모델 크기·입력·하드웨어에 따라 달라진다.","follow":"동일한 데이터셋과 GPU에서 mAP, p95 지연시간, 처리량을 어떻게 비교하겠는가?"},{"id":"Q253","title":"자동차 차선 검출에 U-Net과 전용 Lane Detection 모델 중 무엇을 선택하겠는가?","section":11,"answer":"U-Net은 픽셀 단위 차선 분할에 사용할 수 있다. 차선의 길고 가는 구조와 곡선 기하를 활용하는 UFLD·CLRNet 같은 전용 모델은 구조 표현에 장점이 있다. 차선 가림, 곡률, FPS 요구를 기준으로 선택한다.","follow":"비·야간·마모된 차선에서 어떤 실패 사례를 수집하겠는가?"},{"id":"Q254","title":"DeepLabv3+와 SegFormer는 주행 가능 영역 분할에 어떻게 활용되는가?","section":11,"answer":"DeepLabv3+는 atrous convolution과 디코더를 활용하고 SegFormer는 계층형 Transformer 인코더로 다중 스케일 문맥을 추출한다. 도로·보도·차량·보행자 픽셀을 의미론적으로 분류한다.","follow":"mIoU가 높아도 경계 오판이 위험한 이유는 무엇인가?"},{"id":"Q255","title":"Mask R-CNN의 instance segmentation이 자동차에서 필요한 경우는?","section":11,"answer":"Mask R-CNN은 객체별 box, class와 독립적인 마스크를 예측해 겹친 차량·보행자를 분리할 수 있다. 반면 픽셀마다 하나의 의미 클래스를 정하는 semantic segmentation과 다르다.","follow":"겹친 보행자 검출에서 box mAP와 mask AP를 어떻게 해석하겠는가?"},{"id":"Q256","title":"ByteTrack과 DeepSORT는 자동차 추적에 어떻게 쓰이나?","section":11,"answer":"둘 다 검출 결과를 시간축으로 연결한다. ByteTrack은 낮은 점수 검출도 활용해 연관시키며, DeepSORT는 운동 예측과 외형 임베딩을 이용한다. 이들은 일반적으로 검출 신경망 자체가 아니라 추적 프레임워크다.","follow":"ID switch, HOTA, IDF1과 FPS를 어떻게 함께 평가할 것인가?"},{"id":"Q257","title":"BEVFormer와 BEVDet는 카메라 영상을 왜 BEV로 바꾸는가?","section":11,"answer":"BEV는 여러 카메라 시점을 차량 중심의 조감 좌표계로 통합해 객체 위치와 공간 관계를 다루기 쉽다. BEVFormer는 attention으로 시공간 정보를 결합하고 BEVDet는 이미지 특징을 BEV로 변환해 3D 인지에 활용한다.","follow":"깊이 추정 오류와 카메라 보정 오차가 BEV 결과에 어떻게 전파되는가?"},{"id":"Q258","title":"CenterPoint 같은 3D 객체 검출 모델의 입력과 출력은?","section":11,"answer":"CenterPoint는 LiDAR 포인트클라우드 등의 BEV 특징으로 객체 중심과 3D box, 방향 등을 예측하는 모델이다. 카메라 2D 박스와 달리 3차원 위치·크기를 직접 추정할 수 있다.","follow":"원거리 희소 포인트와 악천후에서 성능을 어떻게 검증하겠는가?"},{"id":"Q259","title":"Monocular Depth 모델(MiDaS·Depth Anything)의 출력은 실제 미터 거리인가?","section":11,"answer":"일반적인 단안 깊이 모델은 상대 깊이 또는 설정에 따른 깊이 추정을 낸다. 출력이 자동으로 절대 미터 거리라고 가정하면 안 되며, 절대 거리에는 스케일 보정과 기하·센서 결합이 필요하다.","follow":"레이더 거리로 단안 깊이의 스케일을 보정할 때 잘못된 매칭을 어떻게 거르겠는가?"},{"id":"Q260","title":"RT-DETR은 YOLO와 무엇이 다르고 왜 자동차에 고려할 수 있는가?","section":11,"answer":"RT-DETR은 Transformer 기반 실시간 객체 검출 모델로 end-to-end set prediction을 활용한다. 버전·구현에 따라 후처리와 지연 특성이 다르므로 NMS 포함 총 추론시간을 비교해야 한다.","follow":"TensorRT 변환 후 실제 p95 latency와 정확도 변화를 어떻게 측정하겠는가?"},{"id":"Q261","title":"Optical Flow 모델 RAFT는 차량 인지에 어떤 정보를 제공하는가?","section":11,"answer":"RAFT는 연속 영상 사이 픽셀 이동 벡터를 추정한다. 움직임 분할, 시간적 일관성 검증, 시각 주행거리 추정의 보조 신호로 쓸 수 있으나 단독으로 물체의 실제 3D 속도를 주지는 않는다.","follow":"카메라 자체 운동과 물체 운동을 어떻게 구분할 것인가?"},{"id":"Q262","title":"차량 인지 모델을 FP16/INT8로 배포할 때 어떤 안전·성능 검증이 필요한가?","section":11,"answer":"TensorRT 등으로 지연시간·VRAM·처리량을 개선하되 소수 클래스, 먼 보행자, 야간, 가림 상황에서 정확도 저하를 별도 확인해야 한다. 평균 FPS만으로 안전성을 판단하면 안 된다.","follow":"INT8 calibration 데이터셋을 어떤 상황별로 층화할 것인가?"},{"id":"Q263","title":"로봇 랜덤 빈피킹에서 YOLO와 instance segmentation 중 무엇이 적합한가?","section":12,"answer":"YOLO box 검출은 후보 위치를 빠르게 찾는 데 유리하고 instance segmentation은 겹친 물체를 개별 픽셀 영역으로 분리한다. 실제 파지에는 깊이·3D 자세·접촉 가능한 표면 정보가 추가로 필요하다.","follow":"서로 겹친 부품과 반사 재질에서 인스턴스 구분 성능을 어떻게 검증하는가?"},{"id":"Q264","title":"GraspNet 기반 6-DoF grasp detection은 무엇을 예측하는가?","section":12,"answer":"RGB-D 또는 포인트클라우드로부터 그리퍼의 3D 위치·방향, 접근 방향 및 grasp 품질 후보를 추정하는 계열이다. 로봇 충돌 검사와 그리퍼 크기·가동 범위 확인은 별도로 필요하다.","follow":"실제 grasp success rate와 오프라인 grasp score가 달라지는 원인은?"},{"id":"Q265","title":"FoundationPose는 로봇 작업에서 어떤 문제를 해결하는가?","section":12,"answer":"FoundationPose는 알려진 물체의 RGB-D 영상 등으로 6D 물체 자세를 추정하고 추적할 수 있는 방법이다. 물체 모델·마스크·카메라 조건 등 적용 전제를 확인해야 한다.","follow":"카메라 좌표계에서 로봇 베이스 좌표계로 자세를 변환하는 과정을 설명하라."},{"id":"Q266","title":"PointNet과 PointNet++는 3D 포인트클라우드를 어떻게 처리하는가?","section":12,"answer":"PointNet은 점별 특징을 공유 MLP로 추출해 순서 불변 집계를 하며 PointNet++는 지역 이웃을 계층적으로 묶어 국소 구조를 학습한다. 포인트 밀도와 샘플링이 성능에 영향을 준다.","follow":"비정형 포인트 수, 노이즈, 누락이 있는 물체 인식에서는 어떻게 전처리하겠는가?"},{"id":"Q267","title":"DGCNN은 PointNet과 어떤 점이 다른가?","section":12,"answer":"DGCNN은 EdgeConv로 점과 이웃 점 사이의 관계 특징을 학습하며 특징 공간의 그래프를 갱신할 수 있다. 형태 구분에 장점이 있지만 kNN 구축과 메모리·연산 비용을 고려해야 한다.","follow":"실시간 로봇에서 kNN 비용을 어떻게 줄이겠는가?"},{"id":"Q268","title":"SAM 계열 분할 모델은 로봇 시각 시스템에서 어떻게 사용할 수 있는가?","section":12,"answer":"SAM은 점·박스 등의 프롬프트를 이용한 범용 마스크 생성에 활용된다. 자동 파지 성공까지 보장하지 않으므로 객체 식별, depth 정합, grasp 계획과 결합해야 한다.","follow":"범용 SAM과 소형 전용 segmentation 모델의 지연시간과 품질을 어떻게 비교하겠는가?"},{"id":"Q269","title":"Keypoint R-CNN이 로봇에서 유용한 경우는?","section":12,"answer":"물체 또는 사람의 주요 관절·랜드마크 좌표를 검출할 수 있다. 조립 정렬, 핸드오버, 작업자 동작 인지 등에 활용하지만 정확한 3D 좌표를 얻으려면 깊이와 보정이 필요하다.","follow":"키포인트 불확실성이 말단 그리퍼 오차로 어떻게 이어지는가?"},{"id":"Q270","title":"RAFT-Stereo 같은 stereo matching 모델의 역할은?","section":12,"answer":"정렬된 좌우 카메라에서 시차 disparity를 예측한다. 기준선과 초점거리로 깊이를 계산할 수 있으며 먼 거리에서는 작은 시차 오차도 큰 깊이 오차가 될 수 있다.","follow":"반복 패턴·투명 물체에서 시차 오류를 어떻게 검출하겠는가?"},{"id":"Q271","title":"로봇 시각의 물체 자세 추정과 객체 검출은 어떻게 다른가?","section":12,"answer":"객체 검출은 2D 위치와 분류를 주로 출력한다. 6D pose estimation은 3D 위치 3자유도와 회전 3자유도를 추정해 물체를 어떻게 집을지 결정하는 데 활용된다.","follow":"대칭 물체에서 회전 오차를 어떤 지표로 평가할 것인가?"},{"id":"Q272","title":"ACT(Action Chunking with Transformers)는 로봇 제어에서 어떤 역할을 하는가?","section":12,"answer":"ACT는 관측과 로봇 상태로부터 여러 시간 단계의 행동 시퀀스를 예측해 모방학습 기반 조작에 활용한다. 인식 전용 모델이 아니라 시각과 제어를 연결하는 정책 모델이다.","follow":"시연 데이터 분포 밖의 물체 배치에서 실패를 어떻게 탐지하겠는가?"},{"id":"Q273","title":"Diffusion Policy는 로봇 조작에서 어떻게 쓰이나?","section":12,"answer":"시각·상태 관측에 조건부로 행동 시퀀스를 생성하는 확산 모델 기반 정책이다. 복수의 가능한 동작을 표현할 수 있지만 추론 비용·제어 주기·안전 제약을 확인해야 한다.","follow":"제어 주기가 20Hz라면 추론 지연과 실행 주기를 어떻게 설계할 것인가?"},{"id":"Q274","title":"RGB-D 로봇 비전 모델을 현장에 배포할 때 어떤 지표가 필요한가?","section":12,"answer":"검출 mAP 외에 자세 오차, 파지 성공률, 사이클 타임, p95 지연, 충돌/미파지 빈도, 재시도 횟수, 도메인 변화에 대한 강건성을 본다.","follow":"시뮬레이터에서 학습한 모델을 실제 카메라·조명으로 옮길 때 무엇을 재검증하는가?"},{"id":"Q275","title":"공장 결함 검사에서 분류·객체 검출·분할을 어떻게 선택하는가?","section":13,"answer":"이미지 전체 합불만 필요하면 classification, 결함 위치 박스가 필요하면 detection, 크기·면적·경계가 중요하면 segmentation이 적합하다. 라벨링 비용·결함 크기·검사 속도도 고려한다.","follow":"약 60개 제품/초와 제품당 12장 조건에서 모델별 지연시간 예산을 어떻게 계산하겠는가?"},{"id":"Q276","title":"U-Net은 표면 결함 분할에 왜 많이 사용되는가?","section":13,"answer":"인코더와 디코더를 skip connection으로 연결해 세밀한 위치 정보와 고수준 문맥을 결합한다. 균열·스크래치처럼 픽셀 경계가 중요한 경우 적용할 수 있다.","follow":"작은 결함에서 IoU 대신 추가로 어떤 지표를 볼 것인가?"},{"id":"Q277","title":"PatchCore는 라벨이 부족한 제조 이상 탐지에 어떻게 동작하는가?","section":13,"answer":"정상 이미지의 pretrained feature patch를 추출해 대표 메모리 뱅크를 만들고 테스트 패치와 최근접 거리로 이상 점수를 계산한다. 주로 정상 데이터만으로 학습 가능한 방식이지만 메모리·검색 비용을 고려해야 한다.","follow":"정상 제품 표면의 자연스러운 변동이 커질 때 false positive를 어떻게 관리하는가?"},{"id":"Q278","title":"PaDiM은 PatchCore와 무엇이 다른가?","section":13,"answer":"PaDiM은 정상 이미지의 위치별 pretrained feature 분포를 다변량 가우시안으로 모델링하고 Mahalanobis distance 등으로 이상을 평가한다. PatchCore는 대표 정상 패치와의 최근접 거리 기반이다.","follow":"위치 정렬이 흔들리는 검사 영상에서는 두 방법이 어떻게 달라지겠는가?"},{"id":"Q279","title":"EfficientAD는 제조 이상 탐지에서 무엇을 최적화하는가?","section":13,"answer":"EfficientAD는 student-teacher 접근 등을 활용해 저지연 anomaly detection을 목표로 하는 기법이다. 실제 장비에서 FPS뿐 아니라 이미지 해상도·후처리·전체 지연을 확인해야 한다.","follow":"PatchCore와 같은 GPU에서 AUROC, F1, p95 지연을 어떻게 비교하겠는가?"},{"id":"Q280","title":"FastFlow는 어떤 방식의 이상 탐지 모델인가?","section":13,"answer":"FastFlow는 정상 특징의 확률 분포를 normalizing flow로 모델링해 낮은 likelihood 영역을 이상으로 판단한다. 학습과 추론에 필요한 GPU 연산 및 특성맵 해상도 비용을 고려해야 한다.","follow":"어떤 제조 결함에서 픽셀 단위 이상 히트맵이 유리한가?"},{"id":"Q281","title":"DRAEM은 표면 결함 탐지에 어떤 데이터를 활용하는가?","section":13,"answer":"DRAEM은 정상 영상에 합성 이상 패턴을 입혀 복원과 판별을 함께 학습하는 접근이다. 합성 결함이 실제 공정 결함을 충분히 대변하지 못할 수 있어 실제 결함으로 검증해야 한다.","follow":"합성 스크래치와 실제 스크래치 간 도메인 차이를 어떻게 측정할 것인가?"},{"id":"Q282","title":"YOLO와 Mask R-CNN을 PCB 검사에 적용할 때 차이는?","section":13,"answer":"YOLO는 부품 누락·배치 불량 후보의 박스를 빠르게 찾는 데 유용하고 Mask R-CNN은 객체별 마스크로 모양·면적을 분리할 수 있다. 정밀 치수 검사는 추가적인 카메라 보정·계측이 필요하다.","follow":"1픽셀 수준의 위치 오차가 불량 판정에 얼마나 영향을 주는지 어떻게 평가하는가?"},{"id":"Q283","title":"ConvNeXt와 Vision Transformer를 산업 이미지 분류에 적용할 때 고려할 점은?","section":13,"answer":"ConvNeXt는 현대화된 CNN 백본이고 ViT는 패치 토큰과 self-attention을 사용한다. 데이터 양, 사전학습, 이미지 해상도, GPU 메모리, 추론 지연을 동일 조건에서 비교해야 한다.","follow":"학습 이미지 수가 작다면 어떤 전이학습·증강 전략을 택하겠는가?"},{"id":"Q284","title":"WM-811K 웨이퍼 맵 결함 분류에는 어떤 모델을 쓸 수 있는가?","section":13,"answer":"웨이퍼 결함 패턴은 공간 분포가 중요해 CNN 분류기(ResNet 등)나 경량 모델을 기준선으로 쓸 수 있다. 클래스 불균형·라벨 품질·웨이퍼별 데이터 누수 방지에 주의한다.","follow":"동일 제조 배치가 train/test 양쪽에 포함되면 왜 위험한가?"},{"id":"Q285","title":"산업 검사에 초고해상도 이미지가 들어오면 모델 추론을 어떻게 구성하는가?","section":13,"answer":"작은 결함이 다운샘플링으로 사라질 수 있어 타일링·overlap·coarse-to-fine·ROI 방식 등을 검토한다. 타일 경계 중복 검출과 데이터 전송·배치 비용을 함께 최적화한다.","follow":"타일 크기와 overlap을 바꿀 때 recall과 p95 latency가 어떻게 변하는지 실험 설계하라."},{"id":"Q286","title":"불량률이 매우 낮은 공장 검사에서 모델 성능을 무엇으로 판단하는가?","section":13,"answer":"Accuracy만으로는 부족하다. 결함 recall/false negative, 정상 false positive, PR-AUC, 결함별 성능과 검사 처리량·운영 재검비용을 함께 본다. 결함 유형별 임계값도 검토한다.","follow":"불량률 0.1%에서 99% accuracy가 쓸모없을 수 있는 이유를 설명하라."},{"id":"Q287","title":"Python의 mutable default argument가 위험한 이유는?","section":14,"answer":"기본 인자는 함수 정의 시 한 번 평가된다. 리스트·딕셔너리를 기본값으로 두면 호출 간 상태가 공유될 수 있으므로 None을 사용하고 함수 내부에서 새 객체를 만든다.","follow":"FastAPI 의존성이나 캐시 구현에서 어떤 버그로 이어질까?"},{"id":"Q288","title":"asyncio와 스레드는 어떻게 다른가?","section":14,"answer":"asyncio는 이벤트 루프에서 협력적 동시성을 제공해 I/O 대기에 유리하고 스레드는 OS 스케줄링을 사용한다. CPU-bound Python 코드는 GIL과 네이티브 라이브러리의 GIL 해제 여부를 고려해야 한다.","follow":"httpx 비동기 요청 100건의 동시성 제한은 어떻게 구현하겠는가?"},{"id":"Q289","title":"FastAPI에서 async def와 def 엔드포인트를 어떻게 선택하는가?","section":14,"answer":"async def는 비동기 I/O를 await하는 작업에 적합하고 def는 동기 라이브러리와 결합할 때 스레드풀에서 실행된다. CPU 연산을 async def 안에서 직접 오래 실행하면 이벤트 루프가 막힌다.","follow":"동기 DB 드라이버와 외부 LLM API를 호출하는 서비스를 설계하라."},{"id":"Q290","title":"Pydantic 모델과 ORM 모델의 역할은 어떻게 다른가?","section":14,"answer":"Pydantic은 입력 검증·직렬화·스키마 생성에 사용하고 ORM은 DB 객체·매핑 및 쿼리 관리에 집중한다. 외부 응답 스키마와 DB 내부 컬럼을 분리하는 편이 안전하다.","follow":"API 요청의 필수값 누락·형식 오류를 어떻게 테스트할까?"},{"id":"Q291","title":"REST API에서 GET·POST·PUT·PATCH의 차이와 멱등성은?","section":14,"answer":"GET은 조회, POST는 생성/처리, PUT은 대상 상태 교체, PATCH는 일부 변경에 사용한다. GET·PUT은 의미적으로 멱등이고 PATCH는 구현에 따라 멱등일 수도 있다.","follow":"네트워크 재시도로 동일 결제가 두 번 실행되지 않으려면?"},{"id":"Q292","title":"FastAPI 서비스의 타임아웃·재시도 정책은 어떻게 설계하는가?","section":14,"answer":"연결·읽기 타임아웃을 분리하고 실패 원인에 따라 제한적 재시도와 지수 백오프·지터를 사용한다. 비멱등 요청은 idempotency key와 중복 처리 방지가 필요하다.","follow":"429와 500 오류를 같은 방식으로 재시도해도 되는가?"},{"id":"Q293","title":"Python 타입 힌트는 런타임 검증을 보장하는가?","section":14,"answer":"타입 힌트만으로 런타임 검사되지 않는다. mypy·pyright 같은 정적 분석기 또는 Pydantic 등 런타임 검증을 별도로 사용한다.","follow":"TypedDict, dataclass, Pydantic BaseModel을 비교하라."},{"id":"Q294","title":"PostgreSQL 인덱스는 언제 성능을 개선하고 언제 손해인가?","section":15,"answer":"선택도가 높은 필터·정렬·조인에서 읽기 비용을 줄일 수 있지만 저장 공간과 INSERT/UPDATE 비용이 증가한다. EXPLAIN ANALYZE로 실제 쿼리 계획과 실행 시간을 확인해야 한다.","follow":"saved_words(user_id,created_at) 조회에 어떤 복합 인덱스가 적합한가?"},{"id":"Q295","title":"트랜잭션과 ACID를 설명하라.","section":15,"answer":"Atomicity·Consistency·Isolation·Durability는 트랜잭션의 핵심 속성이다. 격리 수준은 동시 트랜잭션이 서로의 변경을 관찰하는 범위에 영향을 준다.","follow":"두 작업이 같은 잔여 수량을 읽어 차감하는 lost update를 어떻게 방지하는가?"},{"id":"Q296","title":"Supabase Row Level Security는 무엇을 보호하는가?","section":15,"answer":"RLS는 DB 정책으로 접근 가능한 행을 제어한다. JWT 사용자 식별 및 정책을 올바르게 구성해야 하며 서비스 역할 키는 RLS를 우회할 수 있으므로 브라우저에 공개하면 안 된다.","follow":"사용자별 saved_words가 다른 사용자에게 보이지 않도록 정책을 설명하라."},{"id":"Q297","title":"Redis TTL 캐시는 언제 쓰고 어떤 일관성 문제가 생기는가?","section":15,"answer":"조회 지연이나 반복 API 비용을 줄이기 위해 만료 시간을 정해 데이터를 캐시한다. 데이터 갱신 후 오래된 캐시가 남을 수 있어 무효화 전략과 stampede 방지를 검토한다.","follow":"LLM 응답 캐시의 키에 사용자 권한과 프롬프트 버전을 왜 포함해야 하는가?"},{"id":"Q298","title":"Connection Pool은 왜 필요한가?","section":15,"answer":"매 요청마다 DB 연결을 만드는 비용과 서버 연결 수 증가를 줄인다. 과도한 풀 크기는 오히려 DB 자원을 고갈시키므로 워커 수·동시 요청·DB 한도에 맞춘다.","follow":"FastAPI 다중 워커에서 풀이 몇 개 생성되는지 설명하라."},{"id":"Q299","title":"Optimistic Lock과 Pessimistic Lock을 비교하라.","section":15,"answer":"낙관적 잠금은 버전/조건 검증으로 충돌 시 재시도하며, 비관적 잠금은 DB 잠금으로 동시 수정을 제약한다. 충돌 빈도와 처리량 요구에 따라 선택한다.","follow":"동시에 수정하는 사용자 설정에 어느 방식을 쓰겠는가?"},{"id":"Q300","title":"Vector DB 검색과 PostgreSQL 인덱스 검색은 어떻게 다른가?","section":15,"answer":"벡터 유사도 검색은 임베딩 공간의 근접도를 활용하고 일반 B-tree 인덱스는 정확한 값·범위·정렬에 강하다. 메타데이터 필터와 하이브리드 검색을 함께 설계할 수 있다.","follow":"정확한 문서 ID 조회에 벡터 검색을 쓰면 안 되는 이유는?"},{"id":"Q301","title":"LLM의 토큰과 컨텍스트 윈도우란?","section":16,"answer":"토큰은 모델이 처리하는 입력·출력 단위이며 컨텍스트 윈도우는 한 번에 참고할 수 있는 토큰 수 한계다. 긴 입력은 비용과 지연을 증가시키고 정보 활용도도 떨어질 수 있다.","follow":"검색 문서 30개를 넣는 대신 재랭킹을 사용하는 이유는?"},{"id":"Q302","title":"Temperature와 Top-p는 무엇을 조정하는가?","section":16,"answer":"둘 다 토큰 샘플링 분포에서 선택의 다양성에 영향을 준다. Temperature는 로짓 분포를 조정하고 top-p는 누적확률 기준 후보 집합을 제한한다.","follow":"정확한 JSON 출력 작업에서 생성 설정을 어떻게 선택할까?"},{"id":"Q303","title":"Embedding은 어떻게 RAG 검색에 쓰이는가?","section":16,"answer":"문서와 질문을 벡터로 변환하고 유사도 기반으로 관련 조각을 검색한다. 임베딩 유사성은 사실의 정확성을 보장하지 않으므로 출처·권한·재랭킹 검증이 중요하다.","follow":"한국어·영어 혼합 문서에 어떤 임베딩 평가셋을 구성할까?"},{"id":"Q304","title":"RAG chunk 크기와 overlap의 trade-off는?","section":16,"answer":"큰 청크는 문맥을 유지하지만 무관한 내용도 포함할 수 있고 작은 청크는 검색 정밀도가 좋아질 수 있으나 문맥이 단절될 수 있다. overlap은 누락을 줄이지만 저장량과 중복을 늘린다.","follow":"표·코드·제목 구조가 있는 PDF를 어떻게 분할하겠는가?"},{"id":"Q305","title":"Hybrid Search와 Reranker는 왜 사용하는가?","section":16,"answer":"BM25 같은 키워드 검색과 임베딩 의미 검색을 결합하면 서로 다른 실패를 보완할 수 있다. Reranker는 후보를 더 정밀히 정렬하지만 지연이 늘어난다.","follow":"제품 모델명처럼 정확한 문자열 검색에서 어떤 결합이 적합한가?"},{"id":"Q306","title":"RAG의 Hallucination을 어떻게 줄이는가?","section":16,"answer":"검색 품질 개선, 출처 추적, 답변 불가 시 abstain, 사실 검증, 질문별 근거 범위 제약으로 줄인다. 단순히 프롬프트에 '거짓말하지 마'를 넣는 것만으로 충분하지 않다.","follow":"근거 없는 문장 비율과 citation accuracy를 어떻게 평가할까?"},{"id":"Q307","title":"Structured Output과 Function Calling의 차이는?","section":16,"answer":"Structured Output은 정해진 스키마에 맞는 모델 출력을 얻는 방식이고 Function/Tool Calling은 외부 도구를 호출할 의도와 인자를 구조화한다. 모델 출력은 실제 실행 전 검증이 필요하다.","follow":"검증 실패한 JSON 인자를 자동 실행해도 되는가?"},{"id":"Q308","title":"단순 LLM 호출과 AI Agent의 차이는?","section":17,"answer":"일반적인 Agent는 목표를 위해 모델이 도구·다음 행동을 선택하고 관찰 결과에 따라 후속 행동을 수행하는 루프를 갖는다. 고정 워크플로만 있다고 반드시 Agent인 것은 아니다.","follow":"LLM 없이 조건문으로 처리하는 게 더 안전한 사례는?"},{"id":"Q309","title":"ReAct 패턴은 어떻게 동작하는가?","section":17,"answer":"모델이 추론 기반으로 행동을 선택하고 도구 결과를 관찰해 다음 행동을 이어가는 반복 패턴이다. 실제 서비스에서는 루프 제한·권한·도구 결과 검증이 필수다.","follow":"무한 루프와 불필요한 API 호출을 어떻게 방지하겠는가?"},{"id":"Q310","title":"LangGraph에서 State와 Node, Edge의 역할은?","section":17,"answer":"State는 실행 중 공유·갱신되는 데이터이고 Node는 작업을 수행하며 Edge는 다음 실행 흐름을 결정한다. 조건부 분기와 상태 merge 규칙을 명확히 해야 한다.","follow":"12개 병렬 분기의 결과가 동시에 한 키를 수정하면 어떻게 되는가?"},{"id":"Q311","title":"멀티에이전트에서 Planner·Executor·Critic은 각각 무엇을 하는가?","section":17,"answer":"Planner는 계획, Executor는 실행, Critic은 결과 검토 역할을 맡는다. 명확한 분리가 항상 이익은 아니며 모델 호출 수, 지연, 오류 전파가 커질 수 있다.","follow":"단일 Agent와 3개 Agent를 어떤 지표로 비교하겠는가?"},{"id":"Q312","title":"MCP의 Tool·Resource·Prompt 차이는?","section":17,"answer":"MCP Tool은 실행 가능한 작업, Resource는 읽을 수 있는 컨텍스트, Prompt는 재사용 가능한 프롬프트 템플릿이다. 각 서버가 제공하는 기능을 클라이언트가 표준 방식으로 발견한다.","follow":"MCP 서버가 외부 데이터를 수정하는 도구를 노출할 때 권한은?"},{"id":"Q313","title":"Agent의 Tool Calling은 어떻게 안전하게 검증하는가?","section":17,"answer":"도구별 allowlist·스키마 검증·최소 권한·감사 로그를 적용하고 고위험 작업은 사용자 확인을 요구한다. 프롬프트 인젝션이 포함된 검색 결과를 상위 지시로 신뢰하면 안 된다.","follow":"웹페이지 텍스트가 관리자 API 호출을 지시하면 어떻게 처리하겠는가?"},{"id":"Q314","title":"Agent Memory와 단순 대화 기록 저장의 차이는?","section":17,"answer":"대화 기록은 과거 메시지 보존이며 Agent Memory는 장기 정보 선별·요약·검색과 갱신 정책까지 포함할 수 있다. 민감정보 최소 수집과 만료·삭제 정책이 필요하다.","follow":"사용자별 장기 메모리가 서로 섞이지 않게 설계하라."},{"id":"Q315","title":"워크플로 오케스트레이션과 멀티에이전트는 어떻게 다른가?","section":18,"answer":"오케스트레이션은 작업 순서·병렬성·분기·재시도·상태를 관리하는 상위 개념이며 LLM 에이전트가 필수는 아니다. 결정적인 작업은 일반 코드가 더 적절할 수 있다.","follow":"고정 CI/CD 실행에 LLM Agent를 반드시 넣어야 하는가?"},{"id":"Q316","title":"Fan-out / Fan-in 병렬 실행 패턴은?","section":18,"answer":"독립 작업을 동시에 실행한 후 결과를 수집·합성하는 패턴이다. 부분 실패와 타임아웃 처리, 결과 정렬 및 중복 제거 전략이 필요하다.","follow":"병렬 12개 요청 중 2개가 실패하면 최종 결과를 어떻게 처리하는가?"},{"id":"Q317","title":"Task Queue와 Workflow Engine의 차이는?","section":18,"answer":"작업 큐는 비동기 작업 전달·소비에 초점을 두고 워크플로 엔진은 단계 간 상태·의존성·재시도·장기 실행을 관리한다. 단순한 작업은 큐만으로 충분하다.","follow":"영상 전처리→추론→보고서 생성에 각각 무엇이 필요한가?"},{"id":"Q318","title":"AI 작업의 재시도와 중복 실행 문제를 어떻게 해결하나?","section":18,"answer":"재시도 가능한 오류를 분류하고 멱등 키, 상태 기록, 지수 백오프, dead-letter queue 등의 조합을 쓴다. '정확히 한 번' 실행을 무조건 가정하면 안 된다.","follow":"동일 보고서를 중복 생성하지 않도록 설계하라."},{"id":"Q319","title":"Supervisor가 Agent 작업을 종료시키는 기준은?","section":18,"answer":"성공 조건, 최대 단계 수, 비용·시간 예산, 신뢰도, 도구 실행 횟수, 실패 누적 등 종료 조건을 명시한다. 위험한 외부 작업에는 사람의 승인을 추가한다.","follow":"Critic이 매번 재시도를 요구하면 어떻게 막을 것인가?"},{"id":"Q320","title":"AI 파이프라인에서 상태 복구(Checkpointing)는 왜 필요한가?","section":18,"answer":"장기 실행 중 장애가 생기면 완료한 단계를 다시 수행하지 않고 이어갈 수 있게 한다. 외부 부작용이 있는 단계는 중복 실행 방지도 함께 필요하다.","follow":"DB 갱신 직후 체크포인트 기록 전 장애가 나면 어떻게 대응하나?"},{"id":"Q321","title":"자동복구(Auto-healing)에 AI Agent를 사용하면 좋은 경우와 아닌 경우는?","section":18,"answer":"원인 분류가 복잡하고 실행 전 검토가 필요한 장애에는 보조 분석 도구가 될 수 있다. 반면 단순 프로세스 재시작·헬스체크는 결정적 규칙과 오케스트레이터가 빠르고 예측 가능하다.","follow":"로그를 보고 재시작하는 자동화에서 LLM 비용과 위험을 어떻게 통제하나?"},{"id":"Q322","title":"LLM 서비스에서 오프라인 평가셋을 어떻게 만드는가?","section":19,"answer":"실제 질문을 개인정보 제거 후 유형별로 샘플링하고 정답·근거·합격 조건을 정한다. 데이터 누수와 특정 프롬프트에 대한 과적합을 막기 위해 별도 검증셋을 유지한다.","follow":"RAG 검색 품질과 최종 생성 답변 품질을 어떻게 분리 평가하나?"},{"id":"Q323","title":"Agent 평가에서 성공률 외에 무엇을 봐야 하나?","section":19,"answer":"도구 호출 정확도, 재시도 횟수, 실패 회복력, 완료 시간, 토큰·API 비용, 근거 충실성, 안전 위반을 측정한다.","follow":"간단한 분기 하나에 에이전트 5개를 넣은 효과를 어떻게 검증하나?"},{"id":"Q324","title":"Tracing과 Logging, Metrics의 차이는?","section":19,"answer":"Logging은 이벤트 기록, Metrics는 집계된 수치, Tracing은 분산 호출의 인과 관계와 시간을 추적한다. 공통 request ID와 trace ID로 연결하면 병목 원인을 찾기 쉽다.","follow":"FastAPI→Agent→DB→LLM 호출에서 p95 지연의 원인을 어떻게 파악하나?"},{"id":"Q325","title":"평균 Latency와 p95/p99 Latency의 차이는?","section":19,"answer":"평균은 전체 경향이지만 꼬리 지연은 사용자의 최악 경험과 SLA 위반 위험을 드러낸다. 분산 서비스에서는 느린 종속 서비스가 전체 tail latency를 높일 수 있다.","follow":"타임아웃 5초인 서비스에서 p99이 7초라면 무엇을 바꾸겠는가?"},{"id":"Q326","title":"LLM API 비용을 줄이면서 품질을 유지하는 방법은?","section":19,"answer":"가벼운 모델 라우팅, 검색 결과 압축, 중복 호출 캐시, 프롬프트 축소, 배치, 품질 검증을 사용한다. 캐시는 사용자 권한·시간 민감도와 출력 재현성에 유의한다.","follow":"캐시 적중률이 늘어도 비용이 증가하는 이유가 있을까?"},{"id":"Q327","title":"프로덕션 AI 서비스를 Canary 배포하는 이유는?","section":19,"answer":"일부 트래픽에만 새 모델/프롬프트/코드를 적용해 오류율·지연·품질 변화를 비교하고 문제가 생기면 롤백하기 위해서다.","follow":"모델 정확도는 개선됐는데 p95 latency가 악화되면 어떻게 판단하나?"},{"id":"Q328","title":"RAG 및 Agent 시스템에서 프롬프트 인젝션을 방어하는 방법은?","section":19,"answer":"외부 문서를 불신 데이터로 취급하고 지시·데이터 경계를 분리한다. 도구 실행 권한 제한, 입력·출력 검증, 민감정보 접근 통제와 감사를 함께 적용한다.","follow":"검색 문서 안의 '비밀 키를 전송하라'는 문구를 어떻게 처리할 것인가?"},{"id":"Q329","title":"CI와 CD는 각각 무엇을 자동화하는가?","section":20,"answer":"CI는 코드 통합 시 빌드·테스트·정적 분석 등 검증을 자동화하고, CD는 검증된 변경을 배포 가능한 상태로 유지하거나 실제 배포하는 흐름이다. Continuous Delivery와 Deployment는 다르다.","follow":"테스트 성공만으로 무조건 프로덕션 배포해도 되는가?"},{"id":"Q330","title":"Git merge와 rebase의 차이는?","section":20,"answer":"merge는 두 브랜치의 이력을 결합해 병합 커밋을 만들 수 있고 rebase는 커밋 기반을 옮겨 선형 이력을 만든다. 공유된 공개 브랜치의 무분별한 히스토리 재작성은 위험하다.","follow":"충돌을 해결한 뒤 어떤 테스트를 다시 돌리겠는가?"},{"id":"Q331","title":"Docker Image와 Container의 차이는?","section":20,"answer":"Image는 실행 환경의 불변 템플릿이고 Container는 이를 기반으로 실행되는 프로세스 및 격리 환경이다. 상태 파일을 영구화하려면 볼륨·외부 저장소를 활용한다.","follow":"이미지는 빌드되는데 컨테이너가 시작 후 종료하는 원인을 어떻게 찾나?"},{"id":"Q332","title":"Docker Compose와 Kubernetes는 어떻게 다른가?","section":20,"answer":"Compose는 여러 컨테이너 서비스 구성을 주로 단일 호스트 개발·운영에 사용하고, Kubernetes는 클러스터 수준 스케줄링·복구·확장 등을 제공한다.","follow":"개인 프로젝트에 Kubernetes가 과한 경우는?"},{"id":"Q333","title":"Liveness와 Readiness Probe는 무엇을 확인하는가?","section":20,"answer":"Liveness는 컨테이너 재시작 여부를 결정할 건강 상태, Readiness는 요청을 받을 준비 상태를 판단한다. 일시적인 외부 DB 장애 때문에 무조건 재시작하는 설계는 위험할 수 있다.","follow":"모델 로딩 30초가 필요한 추론 서버의 준비 신호는?"},{"id":"Q334","title":"HTTP 상태 코드 400·401·403·404·429·500·503의 의미는?","section":20,"answer":"400 잘못된 요청, 401 인증 필요, 403 권한 거부, 404 자원 없음, 429 요청 제한, 500 서버 오류, 503 일시적 서비스 불가다. 오류 응답에는 민감한 내부 정보를 노출하지 않는다.","follow":"클라이언트가 재시도할 만한 상태는 무엇인가?"},{"id":"Q335","title":"TCP와 UDP의 차이는?","section":20,"answer":"TCP는 순서·재전송·혼잡 제어를 제공하는 연결 기반 전송이고 UDP는 연결을 설정하지 않는 데이터그램 전송이다. 애플리케이션 요구에 따라 실시간성·신뢰성을 선택한다.","follow":"로봇 위치 명령과 영상 스트리밍에 어떤 전송을 쓰겠는가?"},{"id":"Q336","title":"단위 테스트·통합 테스트·E2E 테스트의 차이는?","section":20,"answer":"단위 테스트는 작은 구성 요소를 격리 검증하고, 통합 테스트는 시스템 구성 요소 간 상호작용을 확인하며, E2E는 사용자 시나리오를 통해 전체 흐름을 검사한다.","follow":"외부 LLM API 호출을 어떤 테스트에서는 mock으로 대체하겠는가?"},{"id":"Q337","title":"Race Condition과 Deadlock의 차이는?","section":20,"answer":"Race Condition은 실행 순서에 따라 결과가 달라지는 문제이고 Deadlock은 서로 필요한 자원을 기다려 진행하지 못하는 상태다. 락 순서 통일과 범위 축소로 위험을 줄인다.","follow":"두 스레드가 서로 다른 순서로 뮤텍스 두 개를 잡을 때 어떻게 고치나?"},{"id":"Q338","title":"Profiling과 Benchmark의 차이는?","section":20,"answer":"Benchmark는 특정 조건에서 시스템 성능을 측정·비교하고 Profiling은 실행 시간·자원 사용의 병목을 추적한다. 측정 워밍업, 입력 크기, 환경 및 통계 분포를 통제한다.","follow":"속도가 2배 빨라졌다는 주장을 어떤 조건에서 검증하겠는가?"},{"id":"Q339","title":"Feature Flag와 Rollback은 어떻게 사용하는가?","section":20,"answer":"Feature Flag는 배포와 기능 노출을 분리해 점진 출시·긴급 비활성화에 사용하고 Rollback은 이전 정상 버전으로 되돌린다. 데이터베이스 스키마 호환성도 고려해야 한다.","follow":"새 DB 컬럼 추가와 앱 롤백이 충돌하지 않게 하려면?"},{"id":"Q340","title":"개발 환경의 비밀 키를 안전하게 관리하는 방법은?","section":20,"answer":"키를 Git에 커밋하지 않고 환경 변수·Secret Manager로 주입하며 최소 권한·주기적 회전·로그 마스킹을 적용한다. 프런트엔드 번들에 들어간 키는 공개된 것으로 본다.","follow":"실수로 API 키를 Git에 올렸을 때 가장 먼저 할 일은?"}];
